POST /v1/customers                 { profile, documents }     -> { customerId, kycStatus }
POST /v1/applications              { customerId, productId, data } -> { applicationId, status: SUBMITTED }
POST /v1/transfers   Idempotency-Key: <uuid>
     { fromAccount, toAccount, amount: {value: '1500.00', currency: 'INR'}, reference }
     -> 201 { transferId, status: PENDING | COMPLETED }
GET  /v1/accounts/{id}/balance     GET /v1/accounts/{id}/statement?from&to

-- transfer 1500 from A to B, atomically
BEGIN;
SELECT balance FROM balances WHERE account_id = 'A' FOR UPDATE;   -- check funds
INSERT INTO journal_entries(entry_id, txn_id) VALUES ($e, $t);
INSERT INTO postings VALUES ($p1, $e, 'A', -1500.00, 'INR'), ($p2, $e, 'B', +1500.00, 'INR');
UPDATE balances SET ledger = ledger - 1500, version = version + 1 WHERE account_id = 'A';
UPDATE balances SET ledger = ledger + 1500, version = version + 1 WHERE account_id = 'B';
INSERT INTO outbox(...) VALUES ('TransferCompleted', ...);
COMMIT;
